using System;using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;
namespace AshkanPharmacy.Forms { public class BackupRestoreCenterForm:Form {
 public BackupRestoreCenterForm(){Text=Localization.Persian?"پشتیبان‌گیری و بازیابی":"Backup & Restore Center";BackColor=Color.FromArgb(233,241,244);Dock=DockStyle.Fill;FormBorderStyle=FormBorderStyle.None;PageChrome.Header(this,Text,Localization.Persian?"تداوم کسب‌وکار و حفاظت از داده":"Business continuity and data protection",Color.FromArgb(43,91,124),Color.FromArgb(30,143,126));Build();}
 void Build(){var p=new RoundedPanel{Left=28,Top=160,Width=900,Height=360,Radius=20,BackColor=Theme.Card,BorderColor=Color.FromArgb(204,221,226)};Controls.Add(p);p.Controls.Add(new Label{Text=Localization.Persian?"Data protection":"Data protection",Left=28,Top=24,Width=350,Height=35,Font=Theme.Font(15,FontStyle.Bold),ForeColor=Theme.Navy});var backup=new AccentButton{Text=Localization.Persian?"ایجاد نسخه پشتیبان":"Create backup",Left=28,Top=90,Width=210,Height=52,BackColor=Theme.Teal,ForeColor=Color.White};backup.Click+=(s,e)=>{try{using(var d=new SaveFileDialog{Filter="SQL backup (*.bak)|*.bak",FileName="PharmaSphere-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".bak"}){if(d.ShowDialog(this)!=DialogResult.OK)return;BackupService.Backup(d.FileName);}MessageBox.Show(Localization.Persian?"نسخه پشتیبان ایجاد شد.":"Backup created.");}catch(Exception ex){MessageBox.Show(ex.Message);}};p.Controls.Add(backup);p.Controls.Add(new Label{Text=Localization.Persian?"• Backup دستی SQL Server\n• Audit عملیات حساس\n• Migration history\n• توصیه: نسخه‌های پشتیبان خارج از دستگاه نگهداری شوند.":"• Manual SQL Server backup\n• Sensitive-operation auditing\n• Migration history\n• Recommendation: keep off-device backup copies.",Left=28,Top=175,Width=700,Height=140,Font=Theme.Font(10),ForeColor=Theme.Muted});}
 } }